/**
 * Types for importing images, SVG included, as modules.
 *
 * `next-env.d.ts` references the same file, but it is generated by `next dev`
 * or `next build` and kept out of version control, so a type check that runs
 * before either — as CI's does — never sees it, and every image import fails to
 * resolve. Referencing it here as well keeps the check independent of whether
 * anything has been built. The two references name one file, so nothing is
 * declared twice.
 */
